<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cargosCorrelativo, eliminarCorrelativo, guardarCorrelativo, listarCorrelativos, opcionesCorrelativos, resetearCorrelativo } from '../services/configuracion'
import type { Correlativo } from '../interfaces/configuracion.interface'
import type { CatalogOption, CargoOption } from '../../interfaces/documento'
const tipos=ref<CatalogOption[]>([]),instancias=ref<CatalogOption[]>([]),cargosFiltro=ref<CargoOption[]>([]),items=ref<Correlativo[]>([]),pagination=reactive({current:1,last:1,total:0})
const filters=reactive({tipo_documento_id:0,instancia_id:0,cargo_id:0,page:1}),form=reactive({tipo_documento_id:0,instancia_id:0,cargo_id:0,numero:0}),formCargos=ref<CargoOption[]>([])
const loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),resetItem=ref<Correlativo|null>(null),resetNumber=ref(0)
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarCorrelativos(filters);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar los correlativos.'}finally{loading.value=false}}
async function filterCargos(){filters.cargo_id=0;cargosFiltro.value=filters.instancia_id?await cargosCorrelativo(filters.instancia_id):[]}
async function formLoadCargos(){form.cargo_id=0;formCargos.value=form.instancia_id?await cargosCorrelativo(form.instancia_id):[]}
async function open(item?:Correlativo){editing.value=item?.id||null;Object.assign(form,item?{tipo_documento_id:item.tipo_documento_id,instancia_id:item.instancia_id,cargo_id:item.cargo_id,numero:item.numero}:{tipo_documento_id:0,instancia_id:0,cargo_id:0,numero:0});formCargos.value=form.instancia_id?await cargosCorrelativo(form.instancia_id):[];modal.value=true}
async function save(){if(!form.tipo_documento_id||!form.instancia_id||!form.cargo_id||form.numero<0){error.value='Complete tipo documental, instancia, cargo y número.';return}saving.value=true;try{await guardarCorrelativo(editing.value,{...form});success.value=editing.value?'Correlativo actualizado.':'Correlativo registrado.';modal.value=false;await load(editing.value?pagination.current:1)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.'}finally{saving.value=false}}
async function reset(){if(!resetItem.value)return;try{await resetearCorrelativo(resetItem.value.id,resetNumber.value);success.value=`Correlativo reiniciado en ${resetNumber.value}.`;resetItem.value=null;await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo reiniciar.'}}
async function remove(i:Correlativo){if(!confirm('¿Eliminar este correlativo?'))return;try{await eliminarCorrelativo(i.id);success.value='Correlativo eliminado.';await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar.'}}
onMounted(async()=>{try{const r=await opcionesCorrelativos();tipos.value=r.tipos_documento;instancias.value=r.instancias;await load()}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo preparar la configuración.'}})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Configuración / Correlativos</nav><header class="hero"><div class="mark">#</div><div><small>Configuración</small><h1>Correlativos documentales</h1><p>Administra la numeración por tipo, instancia y cargo emisor.</p></div><strong>{{pagination.total}} registros</strong><button @click="open()">+ Nuevo correlativo</button></header><div v-if="success" class="flash">✓ {{success}}</div><div v-if="error" class="flash error">{{error}}</div><form class="filters" @submit.prevent="load()"><label><span>Tipo documental</span><select v-model="filters.tipo_documento_id"><option :value="0">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Instancia</span><select v-model="filters.instancia_id" @change="filterCargos"><option :value="0">Todas</option><option v-for="o in instancias" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Cargo</span><select v-model="filters.cargo_id" :disabled="!filters.instancia_id"><option :value="0">Todos</option><option v-for="o in cargosFiltro" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><button>Buscar</button><button type="button" class="clear" @click="Object.assign(filters,{tipo_documento_id:0,instancia_id:0,cargo_id:0});cargosFiltro=[];load()">Limpiar</button></form><div v-if="loading" class="notice">Cargando correlativos…</div><div v-else-if="!items.length" class="notice">No se encontraron correlativos.</div><section v-else class="cards"><article v-for="i in items" :key="i.id"><header><div class="counter">{{i.numero}}</div><div><small>{{i.tipo_documento?.nombre||`Tipo #${i.tipo_documento_id}`}}</small><h2>{{i.instancia?.nombre||'Sin instancia'}}</h2></div></header><dl><div><dt>Cargo emisor</dt><dd>{{i.cargo?.nombre||'—'}}</dd></div><div><dt>Último número</dt><dd>{{i.numero}}</dd></div></dl><footer><button @click="open(i)">Editar</button><button class="reset" @click="resetItem=i;resetNumber=i.numero">Reiniciar</button><button class="delete" @click="remove(i)">Eliminar</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>Numeración documental</small><h2>{{editing?'Editar':'Registrar'}} correlativo</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><label><span>Tipo documental *</span><select v-model="form.tipo_documento_id"><option :value="0" disabled>Seleccione</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Instancia *</span><select v-model="form.instancia_id" @change="formLoadCargos"><option :value="0" disabled>Seleccione</option><option v-for="o in instancias" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Cargo *</span><select v-model="form.cargo_id" :disabled="!form.instancia_id"><option :value="0" disabled>Seleccione</option><option v-for="o in formCargos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Número actual *</span><input v-model.number="form.numero" type="number" min="0"></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></section></div><div v-if="resetItem" class="backdrop" @mousedown.self="resetItem=null"><section class="modal reset-modal"><header><div><small>Reinicio de numeración</small><h2>Reiniciar correlativo</h2></div><button @click="resetItem=null">×</button></header><form @submit.prevent="reset"><p>Indica el último número usado para <b>{{resetItem.tipo_documento?.nombre}}</b>.</p><label><span>Nuevo número</span><input v-model.number="resetNumber" type="number" min="0"></label><footer><button type="button" class="clear" @click="resetItem=null">Cancelar</button><button>Confirmar reinicio</button></footer></form></section></div></div></template>
<style scoped>
.page{--accent:#2878d0;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:1.2rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;font-size:.65rem}.hero>button,.filters button,.pagination button,.cards footer button,.modal footer button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.62rem}.flash{margin-top:14px;padding:11px;border:1px solid #b9dfce;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.68rem}.flash.error{color:#a13f43;border-color:#efcaca;background:#fff4f4}.filters{margin:16px 0;padding:18px;display:grid;grid-template-columns:repeat(3,1fr) auto auto;align-items:end;gap:8px;border:1px solid #e2e7ea;border-radius:11px;background:#fff}label span{display:block;margin-bottom:6px;color:#66737a;font-size:.63rem}input,select{width:100%;height:40px;padding:0 10px;border:1px solid #dae2e6;border-radius:7px;background:#fff;font:inherit;font-size:.68rem}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}.notice{padding:45px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.7rem}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.cards article{border:1px solid #dfe6ea;border-top:3px solid var(--accent);border-radius:10px;background:#fff}.cards article>header{padding:15px;display:flex;align-items:center;gap:10px}.counter{min-width:45px;height:45px;padding:0 7px;display:grid;place-items:center;border-radius:9px;color:var(--accent);background:#eaf3fc;font-weight:700}.cards h2{margin:2px 0;font-size:.78rem}.cards small{color:#89959b;font-size:.57rem}.cards dl{margin:0;padding:0 15px}.cards dl>div{padding:7px 0;display:flex;justify-content:space-between;border-top:1px solid #edf0f2;font-size:.62rem}.cards dd{margin:0;font-weight:600}.cards footer{padding:13px 15px;display:flex;gap:5px}.cards footer button{flex:1}.cards .reset{color:#745511;border-color:#f3d18a;background:#ffedc3}.cards .delete{border-color:#bd5050;background:#bd5050}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,520px);border-radius:12px;background:#fff}.reset-modal{max-width:430px}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal>form{padding:20px}.modal form>label{display:block;margin-bottom:13px}.modal form p{font-size:.68rem}.modal footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:620px){.hero{flex-wrap:wrap}.hero>strong{margin-left:0}.hero>button{width:100%}.cards,.filters{grid-template-columns:1fr}}
</style>
